return {hdnpc0201={id="hdnpc0201",dsc="他曾在朝为官，半生漂泊，倦了趋名逐利，挂冠而归，隐于山野。他着葛巾布袍，一副闲适之姿。",sex="男",age=55,looks=30,showequip={},withCorpse=0},hdnpc0202={id="hdnpc0202",dsc="他曾在朝为官，半生漂泊，倦了趋名逐利，挂冠而归，隐于山野。他以一枝茱萸束发，手提行灯，脚著谢公屐。",sex="男",age=55,looks=30,showequip={},withCorpse=0},hdnpc0203={id="hdnpc0203",dsc="他曾在朝为官，半生漂泊，倦了趋名逐利，挂冠而归，隐于山野。他挽起衣袖，草履沾有黑泥，似刚从田野中回来。",sex="男",age=55,looks=30,showequip={},withCorpse=0}}000000000